import React, { useState } from 'react';
import { Menu, X, Home, ChevronDown, ChevronRight } from 'lucide-react';
import collegeLogo from '../../assets/cec122.png';
import Updates from './Updates.jsx';

const navItems = [
    { name: 'HOME', path: '#home', hasDropdown: false, isHome: true },
    { 
        name: 'ABOUT', path: '#about', hasDropdown: true, 
        dropdownItems: [
            { 
                label: 'Administrations', path: '#administrations', hasSubDropdown: true,
                subItems: [
                    { label: 'Board of Governors', path: '#board-of-governors' },
                    { label: 'Principal', path: '#principal' },
                    { label: 'Administrative Staff', path: '#administrative-staff' },
                    { label: 'Library Staff', path: '#library-staff' }
                ]
            },
            { 
                label: 'Facilities', path: '#facilities', hasSubDropdown: true,
                subItems: [
                    { label: 'FAB Lab', path: '#fab-lab' },
                    { label: 'Library', path: '#library' },
                    { label: 'Laboratories', path: '#labs' },
                    { label: 'Hostel & Mess', path: '#hostel' }
                ]
            },
            { label: 'Our Teachers', path: '#teachers' },
            { 
                label: 'Committees', path: '#committees', hasSubDropdown: true,
                subItems: [
                    { label: 'Parents Teachers Organization', path: '#parents-teachers' },
                    { label: 'Right to Information', path: '#right-to-info' },
                    { label: 'Women Cell', path: '#women-cell' },
                    { label: 'Grievance Redressal', path: '#grievance' },
                    { label: 'Anti Ragging Committee', path: '#anti-ragging' },
                    { label: 'Internal Complaints Committee', path: '#internal-complaints' },
                    { label: 'Intellectual Property Rights Cells', path: '#iprc' },
                    { label: 'Research & Development Cell', path: '#research' },
                    { label: 'SC/ST/OBC Committee', path: '#sc-st-cell' },
                    { label: 'Institution Innovation Council', path: '#iic' },
                    { label: 'Institution', path: '#student-council' },
                    { label: 'Other Committees', path: '#other-committees' }
                ]
            }
        ]
    },
    { 
        name: 'ACADEMICS', path: '#academics', hasDropdown: true,
        dropdownItems: [
            { label: 'Department', path: '#department' },
            { label: 'KTU', path: '#ktu' },
            { label: 'AICTE', path: '#aicte' }
        ]
    },
    {
        name: 'PROGRAMS', path: '#programs', hasDropdown: true,
        dropdownItems: [
            { label: 'BTech', path: '#btech' },
            { label: 'MCA', path: '#mca' },
            { label: 'DOCTORAL program', path: '#doctoral' }
        ]
    },
    {
        name: 'PLACEMENT', path: '#placement', hasDropdown: false
    },
    {
        name: 'ORGANIZATIONS', path: '#organizations', hasDropdown: true,
        dropdownItems: [
            { label: 'IEEE', path: '#ieee' },
            { label: 'FOCES', path: '#foces' },
            { label: 'Naval NCC Unit', path: '#ncc' },
            { label: 'NSS', path: '#nss' },
            { label: 'PRODECC', path: '#prodecc' },
            { label: 'EXCESS', path: '#excess' },
            { label: 'SURGE', path: '#surge' }
        ]
    },
    {
        name: 'DOWNLOADS', path: '#downloads', hasDropdown: false
    },
    {
        name: 'CONTACT US', path: '#contact', hasDropdown: false
    }
];

const NavItem = ({ item, closeMobileMenu }) => {
    const [isMobileExpanded, setIsMobileExpanded] = useState(false);
    const [expandedSubMenu, setExpandedSubMenu] = useState(null);

    const toggleSubMenu = (e, idx) => {
        e.preventDefault();
        setExpandedSubMenu(expandedSubMenu === idx ? null : idx);
    };

    if (!item.hasDropdown) {
        return (
            <li>
                <a 
                    href={item.path} 
                    onClick={closeMobileMenu} 
                    className="flex items-center gap-1 block whitespace-nowrap px-4 py-3 transition hover:bg-coral2 hover:text-gold md:py-[14px]"
                >
                    {item.isHome && <Home size={18} />} {item.name}
                </a>
            </li>
        );
    }

    return (
        <li className="relative group/main">
            {/* Desktop link rendering */}
            <a 
                href={item.path}
                className="hidden md:flex items-center gap-1 whitespace-nowrap px-4 py-[14px] transition hover:bg-coral2 hover:text-gold cursor-pointer"
            >
                {item.name}
                <ChevronDown size={14} className="group-hover/main:rotate-180 transition-transform duration-300" />
            </a>

            {/* Mobile rendering */}
            <div className="md:hidden flex items-center justify-between px-4 py-3 transition hover:bg-coral2 hover:text-gold">
                <a 
                    href={item.path} 
                    onClick={closeMobileMenu} 
                    className="flex-grow whitespace-nowrap font-semibold tracking-[0.03em]"
                >
                    {item.name}
                </a>
                <button 
                    onClick={(e) => { e.preventDefault(); setIsMobileExpanded(!isMobileExpanded); }} 
                    className="p-1 min-w-[32px] flex justify-end"
                >
                    <ChevronDown size={18} className={`transition transform duration-300 ${isMobileExpanded ? 'rotate-180' : ''}`} />
                </button>
            </div>

            {/* Desktop Dropdown */}
            <div className="hidden md:block absolute top-[100%] left-0 bg-coral shadow-[0_10px_30px_rgba(0,0,0,0.15)] min-w-[220px] z-[1000] border-t-2 border-gold rounded-b-md opacity-0 invisible group-hover/main:opacity-100 group-hover/main:visible transition-all duration-300 ease-in-out transform origin-top group-hover/main:translate-y-0 translate-y-2">
                <ul className="flex flex-col py-2">
                    {item.dropdownItems.map((subItem, idx) => (
                        <li key={idx} className={subItem.hasSubDropdown ? "relative group/sub" : ""}>
                            {subItem.hasSubDropdown ? (
                                <>
                                    <div className="flex items-center justify-between px-6 py-2.5 hover:bg-coral2 cursor-pointer group-hover/sub:bg-coral2">
                                        <span className="text-[0.95rem] font-medium tracking-wide text-white/95">{subItem.label}</span>
                                        <ChevronRight size={14} className="text-white/70" />
                                    </div>
                                    <div className="absolute top-0 left-full -ml-[2px] bg-coral shadow-[0_10px_30px_rgba(0,0,0,0.15)] min-w-[200px] border-l-2 border-gold rounded-r-md opacity-0 invisible group-hover/sub:opacity-100 group-hover/sub:visible transition-all duration-300 ease-in-out">
                                        <ul className="flex flex-col py-2">
                                            {subItem.subItems.map((sItem, sIdx) => (
                                                <li key={sIdx}>
                                                    <a 
                                                        href={sItem.path} 
                                                        onClick={closeMobileMenu} 
                                                        className="block px-6 py-2.5 hover:bg-coral2 hover:text-gold transition text-[0.95rem] font-medium tracking-wide text-white/95"
                                                    >
                                                        {sItem.label}
                                                    </a>
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                </>
                            ) : (
                                <a 
                                    href={subItem.path} 
                                    onClick={closeMobileMenu} 
                                    className="block px-6 py-2.5 hover:bg-coral2 hover:text-gold transition text-[0.95rem] font-medium tracking-wide text-white/95"
                                >
                                    {subItem.label}
                                </a>
                            )}
                        </li>
                    ))}
                </ul>
            </div>

            {/* Mobile Dropdown */}
            <div className={`md:hidden overflow-hidden transition-all duration-300 ease-in-out ${isMobileExpanded ? 'max-h-[1000px]' : 'max-h-0'}`}>
                <ul className="bg-coral2 flex flex-col">
                    {item.dropdownItems.map((subItem, idx) => (
                        <li key={idx} className="border-b border-coral/20 border-solid last:border-b-0">
                            {subItem.hasSubDropdown ? (
                                <>
                                    <div className="flex items-center justify-between px-8 py-3 hover:text-gold text-slate-300 transition text-[0.9rem] font-medium tracking-wide">
                                        <div onClick={(e) => toggleSubMenu(e, idx)} className="flex-1 cursor-pointer flex items-center gap-2">
                                            • {subItem.label}
                                        </div>
                                        <button onClick={(e) => toggleSubMenu(e, idx)} className="p-1">
                                            <ChevronDown size={16} className={`transition transform duration-300 ${expandedSubMenu === idx ? 'rotate-180' : ''}`} />
                                        </button>
                                    </div>
                                    <div className={`overflow-hidden transition-all duration-300 ease-in-out ${expandedSubMenu === idx ? 'max-h-[500px]' : 'max-h-0'}`}>
                                        <ul className="bg-coral/80 flex flex-col">
                                            {subItem.subItems.map((sItem, sIdx) => (
                                                <li key={sIdx} className="border-b border-coral2/30 last:border-0">
                                                    <a 
                                                        href={sItem.path} 
                                                        onClick={closeMobileMenu} 
                                                        className="block px-12 py-2.5 hover:text-gold text-slate-300 transition text-[0.85rem] font-medium"
                                                    >
                                                        - {sItem.label}
                                                    </a>
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                </>
                            ) : (
                                <a 
                                    href={subItem.path} 
                                    onClick={closeMobileMenu} 
                                    className="block px-8 py-3 hover:text-gold text-slate-300 transition text-[0.9rem] font-medium tracking-wide"
                                >
                                    • {subItem.label}
                                </a>
                            )}
                        </li>
                    ))}
                </ul>
            </div>
        </li>
    );
};

