                    <ul
                        className={`${isOpen ? 'flex' : 'hidden'} absolute left-0 top-[100%] w-full flex-col bg-coral py-2 text-[1rem] font-semibold tracking-[0.03em] text-white shadow-[0_15px_30px_rgba(0,0,0,0.15)] md:static md:flex md:w-auto md:flex-row md:py-0 md:shadow-none w-[100%] justify-between flex-wrap`}
                    >
                        {navItems.map((item, index) => (
